      return '<a class="btn btn-ghost dash-link" href="../dashboard/Dashboard.html">Dashboard</a>' + '<span class="tier free">Free</span>' + '<button class="btn btn-accent" data-act="subscribe">' + I.crown + 'Upgrade</button>' + '<span class="avatar">A</span>';
